def calculate_weight(a):
    count = {}
    for value in a:
        count[value] = count.get(value, 0) + 1

    weight = 0
    for value, freq in count.items():
        if freq > 1:
            weight += freq * (freq - 1) // 2
    return weight

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        results.append(calculate_weight(a))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
